package com.bank.pctx.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "accounts")
public class Account {

    @Id @Column(name = "account_id") private String accountId;
    @Column(name = "holder_name", nullable = false) private String holderName;
    @Column(nullable = false, precision = 15, scale = 2) private BigDecimal balance;
    @Column(nullable = false) private String status;

    protected Account() {}

    public Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId; this.holderName = holderName; this.balance = balance; this.status = "ACTIVE";
    }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public String getStatus() { return status; }
    public void setBalance(BigDecimal balance) { this.balance = balance; }
    public void setStatus(String status) { this.status = status; }
}
