package com.bank.pctx.service;

import com.bank.pctx.dto.PctxReport;
import com.bank.pctx.model.Account;
import com.bank.pctx.repository.AccountRepository;
import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
@RequiredArgsConstructor
@Slf4j
public class PersistenceContextDemoService {

    private final AccountRepository accountRepo;
    private final EntityManager em;

    // FIRST-LEVEL CACHE: two finds of the same id → ONE SQL, SAME instance (identity map)
    @Transactional(readOnly = true)
    public PctxReport firstLevelCache(String id) {
        Account a1 = em.find(Account.class, id);   // SQL SELECT
        Account a2 = em.find(Account.class, id);   // NO SQL — returned from the context
        boolean same = (a1 == a2);                 // identity guaranteed within one context
        log.info("[1st-level cache] a1 == a2 ? {} (second find hit the persistence context)", same);
        return new PctxReport("first-level-cache", same,
            "Two finds of " + id + " returned the same instance; only ONE SQL SELECT executed.");
    }

    // DIRTY CHECKING: change a managed entity's field — NO explicit save — UPDATE at commit
    @Transactional
    public PctxReport dirtyChecking(String id, BigDecimal newBalance) {
        Account account = accountRepo.findById(id).orElseThrow();  // managed, snapshot taken
        account.setBalance(newBalance);                            // just change the field
        // NO accountRepo.save(...) call! Dirty checking compares snapshot vs current at flush.
        log.info("[dirty checking] changed balance of {} to {} — UPDATE generated automatically at commit",
            id, newBalance);
        return new PctxReport("dirty-checking", true,
            "Field changed on a managed entity; Hibernate flushes UPDATE at commit without save().");
    }

    // TRANSACTION SCOPE: entity returned from a transactional method is DETACHED afterwards
    @Transactional(readOnly = true)
    public Account loadManaged(String id) {
        // managed INSIDE this method; becomes DETACHED once the transaction/context closes
        return accountRepo.findById(id).orElseThrow();
    }

    // BATCH: flush+clear periodically so the persistence context does not grow unbounded
    @Transactional
    public int touchManyAndControlContext(int count) {
        for (int i = 0; i < count; i++) {
            Account a = em.find(Account.class, "SAV2001");
            a.setStatus("ACTIVE"); // managed change
            if (i % 50 == 0) {
                em.flush();   // push queued SQL
                em.clear();   // DETACH all managed entities → release snapshots/memory
            }
        }
        log.info("[context control] flushed+cleared periodically to bound memory over {} iterations", count);
        return count;
    }
}
