package com.bank.pctx.service;

import com.bank.pctx.model.Account;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import static org.assertj.core.api.Assertions.*;

class PersistenceContextTest {

    // A tiny stand-in for the identity map to illustrate first-level cache semantics
    static class IdentityMap {
        private final Map<String, Account> map = new HashMap<>();
        Account find(String id, java.util.function.Supplier<Account> loader) {
            return map.computeIfAbsent(id, k -> loader.get());  // one instance per id
        }
    }

    @Test
    void firstLevelCacheReturnsSameInstance() {
        IdentityMap ctx = new IdentityMap();
        int[] loads = {0};
        java.util.function.Supplier<Account> loader = () -> {
            loads[0]++;
            return new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        };
        Account a1 = ctx.find("SAV2001", loader);
        Account a2 = ctx.find("SAV2001", loader);
        assertThat(a1).isSameAs(a2);     // identity map → same instance
        assertThat(loads[0]).isEqualTo(1); // loaded (SELECT) only ONCE
    }

    @Test
    void dirtyCheckingNeedsNoExplicitSave() {
        // Conceptually: a managed entity's field change is detected via snapshot comparison.
        Account account = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        BigDecimal snapshot = account.getBalance();
        account.setBalance(new BigDecimal("950000"));   // change
        assertThat(account.getBalance()).isNotEqualByComparingTo(snapshot); // dirty → UPDATE at flush
    }

    @Test
    void detachedAfterTransactionScope() {
        // After the transaction/context closes, the entity is DETACHED:
        // further changes are NOT tracked until merge() reattaches it to a new context.
        assertThat("detached").isNotEqualTo("managed");
    }

    @Test
    void flushIsNotCommit() {
        // flush() pushes SQL to the DB within the transaction, but a rollback can still undo it.
        assertThat("flush-within-txn").isNotEqualTo("commit");
    }
}
